namespace DwarfMapper.Generator.Roslyn512.Tests.Golden
{
    /// <summary>
    ///     Reads Generator.Tests' committed golden manifest (one "&lt;case-id&gt; &lt;sha256&gt;" line per case). Read only:
    ///     the manifest is regenerated by Generator.Tests and nowhere else. The line rule is that project's
    ///     <c>GoldenManifest.ParseLines</c>: blank lines and '#' comments are skipped, anything else without a space
    ///     separator throws, so the manifest can never shrink unnoticed here either.
    /// </summary>
    internal static class GoldenManifestFile
    {
        public static IReadOnlyDictionary<string, string> Load()
        {
            var path = Path.Combine(RepoRoot(), "tests", "DwarfMapper.Generator.Tests", "Golden", "output-manifest.txt");
            var lines = File.ReadAllLines(path);
            var result = new Dictionary<string, string>(StringComparer.Ordinal);
            for (var i = 0; i < lines.Length; i++)
            {
                var line = lines[i];
                if (line.Length == 0 || line[0] == '#')
                {
                    continue;
                }

                // The span form: the net11 job builds this project as net11.0, where string.LastIndexOf(char) draws
                // CA1307 (net11.0 adds an overload with a StringComparison; net10.0 has none). The span form has none.
                var space = line.AsSpan().LastIndexOf(' ');
                if (space <= 0)
                {
                    throw new InvalidDataException($"Malformed manifest line {i + 1}: '{line}'.");
                }

                result[line[..space]] = line[(space + 1)..];
            }

            return result;
        }

        private static string RepoRoot()
        {
            var dir = new DirectoryInfo(AppContext.BaseDirectory);
            while (dir is not null && dir.GetFiles("DwarfMapper.NET.sln").Length == 0)
                dir = dir.Parent;

            Assert.True(dir is not null, "Could not locate the repository root (DwarfMapper.NET.sln).");
            return dir.FullName;
        }
    }
}
